import {registerTranslations} from './localization.js';
import {runtimeImages} from './runtime-image-assets.js';
const translations=new Map();
const t=(en,zh)=>{translations.set(en,zh);return en;};
const asset=name=>runtimeImages['spectral/form-research'][name].src;
const icon=(i)=>`<svg viewBox="0 0 160 110" fill="none" stroke="currentColor" stroke-width="1" aria-hidden="true">${[
 '<path d="M30 95V67Q30 6 78 8T127 67V95Z M44 95V71Q44 26 78 22T114 71V95 M59 95Q77 37 98 95"/><path d="M13 95h130M15 60l-10-5m13-17-9-8m32-16-5-10m98 57 12-5m-15-16 10-9"/>',
 '<path d="M50 73Q29 5 80 8T110 77 M55 105l-20-30-9-39q3-10 9 0l9 26-2-24q4-7 8 1l10 34 11 12v20 M105 105l20-30 9-39q-3-10-9 0l-9 26 2-24q-4-7-8 1l-10 34-11 12v20"/>',
 '<path d="M7 100h148 M26 91l-5-38h31l-5 38z M35 53V17m0 17q-26-2-21-19 17 1 21 19m0 8q25-4 22-24-20 6-22 24 M68 90h75v8H68z M64 82h71v8H64z M84 80q-23-4-12-38t29-26q21 5 23 38t-40 26"/>',
 '<path d="M9 75q-10-27 12-30t20 30q-3 10-17 10T9 75 M75 82q-18-4-12-24t20-15q17 5 15 26t-23 13 M126 82h30m-29-5q-8-25 10-26t17 26 M14 44l-5-14 15-16m9 30 6-13 13-7 M123 43l7-23m18 29-4-28 M48 66h9m-3-3 3 3-3 3 M103 66h11m-3-3 3 3-3 3"/>'
 ][i]}</svg>`;
export function spectralFormResearch(img){
 const photo=(name,alt,cls='')=>img(asset(name+'.png'),alt,'fr-photo fr-photo-'+name+' '+cls);
 const groups=[
  ['A. STONE-LIKE KEEPSAKES','A. 石感纪念物',['stone','leaves'],t('Compact volumes, rounded edges and restrained ornament.','紧凑体量、圆润边缘与克制的装饰。'),t('Let significance reside in the relationship, while the object remains visually quiet.','让意义留在关系中，让物件在视觉上保持安静。')],
  ['B. VEILED, RESPONSIVE OBJECTS','B. 朦胧而可感知的物件',['veil','touch','lights'],t('Blurred boundaries, filtered light and gently revealed interiors.','模糊边界、柔化的光与若隐若现的内部。'),t('Suggest presence through partial visibility, leaving room for personal interpretation.','通过局部可见暗示存在，为个人的解读保留空间。')],
  ['C. VESSELS HELD WITH CARE','C. 被温柔托起的器物',['vessels','hold'],t('Enclosing forms, soft necks and a scale associated with holding or placing.','包容的形体、柔和的收口，以及适合捧握或摆放的尺度。'),t('Borrow gestures of care and the language of domestic vessels.','借鉴照护的动作与日常器物的造型语言。')]
 ];
 const qualities=[
  [t('VEILED PRESENCE','朦胧的存在'),t('Perceptual softness → light, reflection and partial visibility.','感知的柔和 → 光、反射与局部可见。'),t('A direction for the response, rather than a literal image of a person.','指向回应的表达方式，而非具象地再现一个人。')],
  [t('TACTILITY','可触性'),t('Rounded contact areas → an inviting two-handed hold.','圆润接触面 → 自然邀请双手捧握。'),t('Soft finishes and rounded contact areas guide the tactile character.','以柔和表面与圆润接触面塑造亲近的触感。')],
  [t('DOMESTIC WARMTH','居家的温度'),t('Warm neutral tones + low visual complexity.','温暖的中性色 + 克制的视觉复杂度。'),t('Aim for an object that can sit among books, plants and familiar possessions.','让物件可以与书籍、植物和熟悉的生活用品并置。')],
  [t('EVERYDAY RITUAL','日常仪式'),t('Pick up → pause → return.','拿起 → 停留 → 放回。'),t('Make remembrance a chosen moment within ordinary life.','让怀念成为日常中可以自主选择的片刻。')]
 ];
 const steps=[[t('01 Enclose','01 包容'),t('A compact vessel.','紧凑而包容的器形。')],[t('02 Incline','02 微倾'),t('Reveal the responsive surface.','以缓坡呈现回应界面。')],[t('03 Soften','03 柔化'),t('Integrate the front recess.','融入柔和的前侧凹口。')]];
 const html=`<section class="sf-page fr-page" id="sf-03" aria-labelledby="fr-title">
 <div class="fr-running"><span>${t('SPECTRAL FLUID / VISUAL RESEARCH TO FORM','灵韵光谱 / 从视觉调研到形态')}</span><span>${t('04 / RITUAL, MATERIAL & FORM','04 / 仪式、材料与形态')}</span></div>
 <header class="fr-header"><h2 id="fr-title">${t('MAKING REMEMBRANCE FEEL AT HOME.','让怀念，自然融入家中。')}</h2><div><p>${t('How might a death-related object feel warm, approachable and welcome in an East Asian home?','在东亚家庭的语境下，如何让与死亡有关的物件充满温度、让人愿意亲近并摆在家中？')}</p><small>${t('A situated design question: family beliefs and mourning practices differ.','一个具体语境下的设计问题：家庭信仰与纪念习惯各不相同。')}</small></div><aside>${t('OBJECTS PEOPLE LIVE WITH CAN ALSO HOLD WHAT MATTERS.','日常相伴的物件，也能承载珍视的关系。')}</aside></header>
 <div class="fr-grid"><div class="fr-references"><h3 class="fr-tag">${t('01 / Looking at everyday rituals','01 / 观察日常仪式')}</h3>${groups.map(([en,zh,photos,observed,reading])=>`<article class="fr-reference"><h4>${t(en,zh)}</h4><div class="fr-reference-row"><div class="fr-photo-group">${photos.map(p=>photo(p,p)).join('')}</div><div><b>${t('Observed:','观察：')}</b><p>${observed}</p><b>${t('Design reading:','设计解读：')}</b><p>${reading}</p></div></div></article>`).join('')}<small>${t('Visual observations from my reference collection; original product functions are not assumed.','基于个人参考图集的视觉观察；不据此推断原产品功能。')}</small></div>
 <div class="fr-qualities"><h3 class="fr-tag">${t('02 / Translating qualities into decisions','02 / 从特质到设计决策')}</h3>${qualities.map(([h,p,n],i)=>`<article class="fr-quality"><span>0${i+1}</span><div><h4>${h}</h4><p>${p}</p><small>${n}</small></div>${icon(i)}</article>`).join('')}<aside class="fr-transfer">${t('Transfer qualities and gestures, rather than reproduce a religious symbol.','转译特质与动作，而非直接复制宗教符号。')}</aside></div>
 <div class="fr-form"><h3 class="fr-tag">${t('03 / From reference to form','03 / 从参考到形态')}</h3><div class="fr-annotated">${photo('linework','Three-quarter contour drawing with a gently inclined top','fr-main-art')}<svg class="fr-leaders" viewBox="0 0 600 360" fill="none" stroke="#333" stroke-width="1" aria-hidden="true"><path d="M137 37h30l44 36 M109 198h33l42-26 M494 174l-29 22"/><g fill="#333"><circle cx="211" cy="73" r="2.5"/><circle cx="184" cy="172" r="2.5"/><circle cx="465" cy="196" r="2.5"/></g></svg><div class="fr-callout fr-top"><b>${t('Gently inclined surface','微倾的观赏界面')}</b><p>${t('Makes fluid and light visible from a seated position.','让坐姿下的流体与光更易被看见。')}</p></div><div class="fr-callout fr-front"><b>${t('Soft front recess','柔和的前侧凹口')}</b><p>${t('Preserves the flowing silhouette and leaves an opening for the projector.','保持外壳流线，并为投影仪留出出光孔隙。')}</p></div><div class="fr-callout fr-side"><b>${t('Continuous rounded body','连续圆润的体量')}</b><p>${t('Proposes a gentle hand-to-object transition.','提出柔和的手与物接触过渡。')}</p></div></div>
 <div class="fr-bottom"><div class="fr-studies"><h4>${t('Form translation studies','形态转译推敲')} <small>/ ${t('proposed reasoning','设计推导')}</small></h4><div class="fr-steps">${steps.map(([h,p],i)=>`<figure><div class="fr-step-art fr-step-${i}"><img src="${asset('evolution.png')}" alt="${h}" loading="lazy"></div><figcaption><h4>${h}</h4><p>${p}</p></figcaption></figure>`).join('')}</div></div><div class="fr-cmf">${img('assets/spectral/product.png','Spectral Fluid product rendering','fr-render')}<div class="fr-swatches"><div><i></i><small>${t('Warm ivory','暖象牙白')}</small></div><div><i></i><small>${t('Soft matte shell','柔和哑光外壳')}</small></div><div><i></i><small>${t('Reflective fluid','反射流体')}</small></div></div></div></div><small class="fr-validation">${t('Form decisions connect the hand, the viewing surface and the home.','围绕手的接触、观看界面与居家语境推敲形态。')}</small></div></div>
 <footer class="fr-footer"><div><h3 class="fr-tag">${t('Design direction','设计方向')}</h3><h4>${t('A vessel for remembrance. A familiar presence in the home.','承载怀念的器物，家中熟悉的陪伴。')}</h4><p>${t('Keep personal meaning, optional ritual and domestic belonging at the centre of the form.','让个人意义、自主的仪式与居家的归属感成为形态的核心。')}</p></div><div><h3 class="fr-tag">${t('Design considerations','设计思考')}</h3><div class="fr-questions"><p>${t('Would people display it openly?','人们愿意将它摆在家中吗？')}</p><p>${t('Does it invite comfortable touch?','它能邀请舒适的触摸吗？')}</p><p>${t('How do different families read its symbolism?','不同家庭如何理解其象征意义？')}</p></div></div><small>${t('Visual research and form translation by the author. Reference images belong to their original owners.','作者的视觉调研与形态转译；参考图片归原作者所有。')}</small></footer></section>`;
 registerTranslations([...translations]);
 return html;
}
